import axios from "axios";

const API_URL = "http://localhost:8000/api"; // или твой backend

export const uploadThesis = async (formData) => {
  const response = await axios.post(
    `${API_URL}/upload/`,
    formData,
    {
      headers: {
        "Content-Type": "multipart/form-data",
      },
    }
  );
  return response.data;
};

export const getResult = async (thesisId) => {
  const response = await axios.get(
    `${API_URL}/thesis/result/${thesisId}/`
  );
  return response.data;
};

export const getMyReports = async () => {
  const response = await axios.get(`${API_URL}/thesis/my-reports/`);
  return response.data;
};
